  // ---- data loading (the ruleset JSON is still read at runtime) ----
  /// Populates this character from a ruleset data record (archetype);
  /// ranged values are picked at random.
  void fromJson(const rpg_os::Json &record) {
    rpg_os::DefaultRandom rng;
    fromJson(record, rpg_os::Variance::Random, rng);
  }

  /// As above, but picks ranged values according to `variance` (weakest,
  /// weak, average, strong, strongest) with the caller-supplied RNG.
